"""Report builders: one small formatting function per report section."""


def section_01(rows):
    """Format section 1 as aligned text lines."""
    width = max((len(str(row)) for row in rows), default=0)
    header = "Section 1".ljust(width)
    body = [str(row).rjust(width) for row in rows]
    return [header, *body]


